// ---- the entry table --------------------------------------------------------------
// name + the ADDRESS OF THE C ENTRY ITSELF. The address is the point: an entry a
// row derives but nobody defined is a LINK error naming the symbol, and one nobody
// declared is a compile error -- neither can reach a run and read as working. The
// runtime table libmh_in_unbound walks is a MUTABLE copy of this, so a selftest can
// punch a hole (the hostapitest holey-table arm) without touching generated code.
struct entry_row {
    const char *name;
    const void *impl;
};

